def evaluate(expr: str) -> float:
    """
    Evaluates a mathematical expression represented as a string.
    Uses the Shunting Yard algorithm to parse the expression and 
    applies the Reverse Polish Notation (RPN) to evaluate the result.
    """

    def precedence(op: str) -> int:
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def apply_operator(operators: list, values: list) -> None:
        right = values.pop()
        left = values.pop()
        op = operators.pop()
        if op == '+':
            values.append(left + right)
        elif op == '-':
            values.append(left - right)
        elif op == '*':
            values.append(left * right)
        elif op == '/':
            values.append(left / right)

    def shunting_yard(expression: str) -> list:
        output = []
        operators = []
        index = 0
        while index < len(expression):
            char = expression[index]
            if char.isspace():
                index += 1
                continue
            if char.isdigit() or char == '.':
                num = ''
                while index < len(expression) and (expression[index].isdigit() or expression[index] == '.'):
                    num += expression[index]
                    index += 1
                output.append(float(num))
            elif char in "+-*/":
                while (operators and precedence(operators[-1]) >= precedence(char)):
                    apply_operator(operators, output)
                operators.append(char)
                index += 1
            elif char == '(':
                operators.append(char)
                index += 1
            elif char == ')':
                while operators and operators[-1] != '(':
                    apply_operator(operators, output)
                operators.pop()  # Remove the '('
                index += 1

        while operators:
            apply_operator(operators, output)

        return output

    rpn = shunting_yard(expr)
    return rpn[0]

