def evaluate(expr: str) -> float:
    """
    Evaluates a mathematical expression represented as a string.
    This implementation employs the Shunting Yard algorithm to convert the 
    expression into Reverse Polish Notation (RPN), which is then evaluated 
    using a stack-based approach.
    """

    def precedence(op: str) -> int:
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def to_rpn(expression: str):
        output = []
        operators = []
        i = 0

        while i < len(expression):
            if expression[i].isspace():
                i += 1
                continue

            if expression[i].isdigit() or expression[i] == '.':
                start = i
                while (i < len(expression) and 
                       (expression[i].isdigit() or expression[i] == '.')):
                    i += 1
                output.append(float(expression[start:i]))
                continue

            if expression[i] == '(':
                operators.append(expression[i])
            elif expression[i] == ')':
                while operators and operators[-1] != '(':
                    output.append(operators.pop())
                operators.pop()
            else:
                while (operators and 
                       precedence(operators[-1]) >= precedence(expression[i])):
                    output.append(operators.pop())
                operators.append(expression[i])
            i += 1

        while operators:
            output.append(operators.pop())

        return output

    def evaluate_rpn(rpn):
        stack = []

        for token in rpn:
            if isinstance(token, float):
                stack.append(token)
            else:
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    stack.append(a / b)

        return stack[0]

    rpn = to_rpn(expr)
    return evaluate_rpn(rpn)

def evaluate(expr: str) -> float:
    """
    Evaluates a mathematical expression represented as a string.
    This implementation uses a recursive descent parsing technique to build
    an expression tree and then evaluates it according to operator precedence.
    """

    def parse_expression(index):
        """Parse a full expression."""
        left, index = parse_term(index)
        while index < len(expr) and expr[index] in ('+', '-'):
            operator = expr[index]
            index += 1
            right, index = parse_term(index)
            left = (left, operator, right)  # Construct a tree node
        return left, index

    def parse_term(index):
        """Parse a term (handles multiplication and division)."""
        left, index = parse_factor(index)
        while index < len(expr) and expr[index] in ('*', '/'):
            operator = expr[index]
            index += 1
            right, index = parse_factor(index)
            left = (left, operator, right)  # Construct a tree node
        return left, index

    def parse_factor(index):
        """Parse a factor (handles numbers and parentheses)."""
        if expr[index] == '(':
            index += 1
            result, index = parse_expression(index)
            index += 1  # Skip the closing parenthesis
            return result, index
        else:
            start = index
            while index < len(expr) and (expr[index].isdigit() or expr[index] == '.'):
                index += 1
            return float(expr[start:index]), index

    def evaluate_tree(node):
        """Recursively evaluate the expression tree."""
        if isinstance(node, float):
            return node
        left, operator, right = node
        left_value = evaluate_tree(left)
        right_value = evaluate_tree(right)
        if operator == '+':
            return left_value + right_value
        elif operator == '-':
            return left_value - right_value
        elif operator == '*':
            return left_value * right_value
        elif operator == '/':
            return left_value / right_value

    parsed_expression, _ = parse_expression(0)
    return evaluate_tree(parsed_expression)

